const body = $json.body ?? $json;

function requiredString(value, field) {
  const text = String(value ?? '').trim();
  if (!text) {
    throw new Error(`Campo obrigatorio ausente: ${field}`);
  }
  return text;
}

function optionalString(value) {
  const text = String(value ?? '').trim();
  return text || null;
}

const email = requiredString(body.email, 'email').toLowerCase();
const password = requiredString(body.password, 'password');

return [{
  json: {
    app: optionalString(body.app) ?? 'dental-aura-clinic',
    email,
    password,
    source: optionalString(body.source) ?? 'admin_login'
  }
}];

const auth = $json;
const input = $('Normalizar credenciais').first().json;

if (!auth?.access_token || !auth?.refresh_token) {
  throw new Error('A autenticacao nao retornou access_token e refresh_token.');
}

const filters = [];

if (auth.user?.id) {
  filters.push(`supabase_user_id.eq.${auth.user.id}`);
}

if (auth.user?.email) {
  filters.push(`email.eq.${auth.user.email}`);
}

if (!filters.length) {
  throw new Error('A autenticacao nao retornou identificadores para validar a role admin.');
}

const orFilter = encodeURIComponent(`(${filters.join(',')})`);
const roleQueryUrl = `${$env.SUPABASE_URL}/rest/v1/access_roles?select=id&active=eq.true&role=eq.admin&or=${orFilter}&limit=1`;

return [{
  json: {
    app: input.app,
    email: input.email,
    role_query_url: roleQueryUrl,
    session: {
      access_token: auth.access_token,
      expires_at: auth.expires_at ?? null,
      expires_in: auth.expires_in ?? null,
      refresh_token: auth.refresh_token,
      token_type: auth.token_type ?? 'bearer',
      user: auth.user ?? null
    },
    source: input.source,
    user: auth.user ?? null
  }
}];

const roleRows = Array.isArray($json) ? $json : [];
const auth = $('Preparar validacao admin').first().json;

if (!roleRows.length) {
  throw new Error('Sua conta nao possui role admin na base de autenticacao ativa.');
}

return [{
  json: {
    ok: true,
    source: 'n8n',
    app: auth.app,
    email: auth.email,
    session: auth.session,
    user: auth.user
  }
}];
